L["Polishing the Gnomish Shortcut-o-Tron..."] = "Gnomischer Abkürzomat wird poliert..."
L["Checking behind the waterfall..."] = "Schaue hinter dem Wasserfall nach..."
L["Convincing the kodo to take the other path..."] = "Überrede den Kodo, den anderen Weg zu nehmen..."
L["Consulting a suspiciously old map..."] = "Befrage eine verdächtig alte Karte..."
L["Measuring the Deeprun Tram with a ruler..."] = "Vermesse die Tiefenbahn mit dem Lineal..."
L["Waiting for the goblin cartographer to sober up..."] = "Warte, bis der Goblinkartograf wieder nüchtern ist..."
L["Checking the shortcut for Defias..."] = "Prüfe die Abkürzung auf Defias..."
L["Counting the stairs in Ironforge..."] = "Zähle die Treppen in Eisenschmiede..."
L["|cff40ff40Arrived|r"] = "|cff40ff40Angekommen|r"
L["|cffffd100Turn in the quest|r"] = "|cffffd100Quest abgeben|r"
L["|cffffd100In the quest area|r"] = "|cffffd100Im Questgebiet|r"
L["No way there found"] = "Kein Weg dorthin gefunden"
L["That spot can't be reached on foot from here (a cliff in the way)."] = "Diese Stelle ist von hier aus zu Fuß nicht erreichbar (eine Klippe ist im Weg)."
L["|cffffd100Use %s|r (to %s)"] = "|cffffd100%s benutzen|r (nach %s)"
L["|cffffd100Learn the flight path, then fly to %s|r"] = "|cffffd100Flugroute erlernen, dann nach %s fliegen|r"
L["Board the %s to %s"] = "Einsteigen: %s nach %s"
L["to the %s (then to %s)"] = "zu: %s (dann nach %s)"
L["|cffffffffETA %s|r"] = "|cffffffffAnkunft in %s|r"
L["All stops: %s"] = "Alle Halte: %s"
L["Next %d stops: %s"] = "Nächste %d Halte: %s"
L["|cffffd100! In a quest area|r"] = "|cffffd100! Im Questgebiet|r"
L["Defeat %s"] = "Besiege %s"
L["Defeat the boss"] = "Besiege den Boss"
L["Upstairs: %s"] = "Nach oben: %s"
L["Downstairs: %s"] = "Nach unten: %s"
L["Below you (down a lift)"] = "Unter dir (Aufzug runter)"
L["Above you (up a lift)"] = "Über dir (Aufzug hoch)"
L["Below you, %s down"] = "Unter dir, %s tiefer"
L["Above you, %s up"] = "Über dir, %s höher"
L["Press a key..."] = "Drück eine Taste..."
L["Not bound"] = "Nicht belegt"
L["|cffff6060Not in combat.|r"] = "|cffff6060Nicht im Kampf.|r"
L["Was: %s"] = "Vorher: %s"
L["|cffff6060That key can't be used.|r"] = "|cffff6060Diese Taste kann nicht genutzt werden.|r"
L["Click, then press a key (Shift, Ctrl or Alt with it if you like) or a controller button. The same key shows and hides the map. Escape cancels, right-click clears it. Also in the game's Key Bindings, under AddOns, and in Options > Controller."] = "Klicken, dann eine Taste (wahlweise mit Umschalt, Strg oder Alt) oder eine Controllertaste drücken. Dieselbe Taste zeigt und verbirgt die Karte. Esc bricht ab, Rechtsklick löscht sie. Auch in der Tastaturbelegung des Spiels unter AddOns und unter Optionen > Controller."
L["Press a key or button..."] = "Drück eine Taste oder Controllertaste..."
L["|cffff6060Controller UI on: a keyboard key only (its tooltip says why).|r"] = "|cffff6060Controller-UI an: nur eine Tastaturtaste (der Tooltip sagt, warum).|r"
L["Quick Find: no %s known on %s, so no route off it. Search Places lists the ones elsewhere."] = "Schnellfinder: kein %s bekannt auf %s, also keine Route von dort weg. Orte suchen listet die anderswo."
L["Thanks to |cffffd100jigrobbulus|r, creator of OpenMap, for making it open source, so its stitched world map could be built into AzerothGPS as the OpenMap map style. Click the address to select it, then Ctrl+C to copy it:"] = "Danke an |cffffd100jigrobbulus|r, den Schöpfer von OpenMap, dafür, es als Open Source freizugeben, sodass seine zusammengesetzte Weltkarte als Kartenstil OpenMap in AzerothGPS eingebaut werden konnte. Klick die Adresse an, um sie zu markieren, dann Strg+C zum Kopieren:"
L["|cffffd100What is kept|r"] = "|cffffd100Was gespeichert wird|r"
L["Roads and walls you draw or erase with the road tools, your pins, and the way you went when you reached a stop clearly faster than estimated. Positions, and your pins' names and icons: no character or realm names. Copy Map Data... includes what you tick there."] = "Straßen und Mauern, die du mit den Straßenwerkzeugen zeichnest oder radierst, deine Pins und der Weg, auf dem du einen Halt deutlich schneller als geschätzt erreicht hast. Positionen sowie Namen und Symbole deiner Pins: keine Charakter- oder Realmnamen. \"Kartendaten kopieren...\" enthält, was du dort ankreuzt."
L["|cffffd100Where it is kept|r"] = "|cffffd100Wo es gespeichert wird|r"
L["On your PC, in this addon's saved variables (WTF\\Account\\<account>\\SavedVariables\\AzerothGPS.lua). Addons can't send anything from the game."] = "Auf deinem PC, in den gespeicherten Variablen dieses AddOns (WTF\\Account\\<account>\\SavedVariables\\AzerothGPS.lua). AddOns können nichts aus dem Spiel versenden."
L["|cffffd100How to share your roads, walls and pins|r"] = "|cffffd100So teilst du deine Straßen, Mauern und Pins|r"
L["1. Type |cffffd100/reload|r (it saves all your edits, so every one is copied), then click |cffffd100Copy Map Data...|r and press |cffffd100Ctrl+C|r."] = "1. Gib |cffffd100/reload|r ein (das speichert alle Änderungen, damit jede kopiert wird), klick dann auf |cffffd100Kartendaten kopieren...|r und drück |cffffd100Strg+C|r."
L["2. Paste it in either place (click an address below, Ctrl+C, and open it in your browser):"] = "2. Füge es an einer dieser Stellen ein (Adresse unten anklicken, Strg+C, im Browser öffnen):"
L["    |cffffd100Report form|r: the first address is the report form on azerothgps.com."] = "    |cffffd100Meldeformular|r: die erste Adresse ist das Meldeformular auf azerothgps.com."
L["    |cffffd100Discord|r: the second is the AzerothGPS Discord."] = "    |cffffd100Discord|r: die zweite ist der AzerothGPS-Discord."
L["3. Name the zone and say what you fixed."] = "3. Nenne die Zone und sag, was du korrigiert hast."
L["Roads and walls that check out are added in a later version, for everyone. Your pins stay yours, to share with"] = "Straßen und Mauern, die sich bestätigen, kommen in einer späteren Version für alle hinzu. Deine Pins bleiben deine, zum Teilen mit"
L["other players as you like: they're never put into AzerothGPS's own data."] = "anderen Spielern nach Belieben: sie kommen nie in die eigenen Daten von AzerothGPS."
L["Nothing picked to copy: tick what to include above."] = "Nichts zum Kopieren gewählt: kreuze oben an, was dazugehört."
L["%d line of map data. Press |cffffd100Ctrl+C|r to copy (it's all selected), then paste it in the report form on azerothgps.com or on the AzerothGPS Discord (see How to share). Missing an edit? Type |cffffd100/reload|r and copy again."] = "%d Zeile Kartendaten. Drück |cffffd100Strg+C|r zum Kopieren (alles ist markiert) und füge sie im Meldeformular auf azerothgps.com oder im AzerothGPS-Discord ein (siehe \"So teilst du\"). Fehlt eine Änderung? Gib |cffffd100/reload|r ein und kopiere erneut."
L["%d lines of map data. Press |cffffd100Ctrl+C|r to copy (it's all selected), then paste it in the report form on azerothgps.com or on the AzerothGPS Discord (see How to share). Missing an edit? Type |cffffd100/reload|r and copy again."] = "%d Zeilen Kartendaten. Drück |cffffd100Strg+C|r zum Kopieren (alles ist markiert) und füge sie im Meldeformular auf azerothgps.com oder im AzerothGPS-Discord ein (siehe \"So teilst du\"). Fehlt eine Änderung? Gib |cffffd100/reload|r ein und kopiere erneut."
L["no map data to share yet: roads or walls you drew or erased, faster trips, pins"] = "noch keine Kartendaten zum Teilen: gezeichnete oder radierte Straßen und Mauern, schnellere Wege, Pins"
L["Your Map Data"] = "Deine Kartendaten"
L["Unticked: left out of the copy."] = "Nicht angekreuzt: wird nicht kopiert."
L["Sharing Your Map Data"] = "Kartendaten teilen"
L["Copy Map Data..."] = "Kartendaten kopieren..."
L["AzerothGPS's work: measuring..."] = "Arbeit von AzerothGPS: wird gemessen..."
L["AzerothGPS's work: %.1f ms a second, %.1f%% of the time"] = "Arbeit von AzerothGPS: %.1f ms pro Sekunde, %.1f%% der Zeit"
L["AzerothGPS Options"] = "AzerothGPS-Optionen"
L["General"] = "Allgemein"
L["The GPS map window. Also: left-click the minimap button, a key (at the end of this section), or /agps toggle."] = "Das GPS-Kartenfenster. Auch: Linksklick auf den Minikartenbutton, eine Taste (am Ende dieses Abschnitts) oder /agps toggle."
L["Lock map position"] = "Kartenposition sperren"
L["Locks the map in place. Unlocked: drag the window frame's title bar (or the Move tab without the frame, or Shift+drag the map) to move it."] = "Hält die Karte fest. Entsperrt: zum Verschieben die Titelleiste des Fensterrahmens ziehen (ohne Rahmen den Reiter \"Bewegen\", oder Umschalt+Ziehen auf der Karte)."
L["Window frame"] = "Fensterrahmen"
L["The game-style window frame around the map: title bar, logo and close button. Off: just the map."] = "Der Fensterrahmen im Spielstil um die Karte: Titelleiste, Logo und Schließen-Button. Aus: nur die Karte."
L["Reopen following me"] = "Beim Öffnen mir folgen"
L["With a route set: if you hid the map while looking around it (dragged or zoomed out to the world map), it opens again centered on you, following your position. Off: it opens where you left it (the button at the bottom right brings it back to you)."] = "Mit gesetzter Route: hast du die Karte beim Umsehen verborgen (verschoben oder bis zur Weltkarte herausgezoomt), öffnet sie sich wieder auf dich zentriert und folgt deiner Position. Aus: sie öffnet sich dort, wo du sie verlassen hast (der Button unten rechts holt sie zu dir zurück)."
L["Zoom in near a stop"] = "Nahe einem Halt hineinzoomen"
L["Within 50 yards of your next stop, the map zooms in smoothly so you can see exactly where it is, and back out to your zoom once you're there. Zooming yourself keeps your zoom for that stop."] = "Innerhalb von 50 yd vor deinem nächsten Halt zoomt die Karte sanft hinein, damit du genau siehst, wo er ist, und danach zurück auf deinen Zoom. Zoomst du selbst, bleibt dein Zoom für diesen Halt."
L["Turn the map with me"] = "Karte mit mir drehen"
L["On: the map turns so that where you face is up (heading-up). Off: north stays up and the arrow turns. Not in the game's world map: north stays up there, as on the game's map."] = "An: die Karte dreht sich, sodass deine Blickrichtung oben ist. Aus: Norden bleibt oben und der Pfeil dreht sich. Nicht in der Weltkarte des Spiels: Dort bleibt Norden oben, wie auf der Karte des Spiels."
L["Size"] = "Größe"
L["Can't be smaller than %d with your quick buttons: move some to the menu or hide them (Quick buttons page)."] = "Mit deinen Schnellbuttons nicht kleiner als %d: verschiebe einige ins Menü oder blende sie aus (Seite Schnellbuttons)."
L["Width"] = "Breite"
L["Can't be narrower than %d with your quick buttons going right: put some going up or hide them (Quick buttons page)."] = "Mit deinen Schnellbuttons nach rechts nicht schmaler als %d: setze einige nach oben oder blende sie aus (Seite Schnellbuttons)."
L["Height"] = "Höhe"
L["Resize from the corner"] = "Größe über die Ecke ändern"
L["Drag the map window's bottom-right corner to resize it (on by default). While Lock map position is on, the corner doesn't resize; unlock the map and it does again. Off: the size only changes with the slider above."] = "Zieh die untere rechte Ecke des Kartenfensters, um die Größe zu ändern (standardmäßig an). Solange \"Kartenposition sperren\" an ist, ändert die Ecke nichts; entsperre die Karte, dann wieder. Aus: die Größe ändert sich nur mit dem Regler oben."
L["Any shape"] = "Beliebige Form"
L["Dragging the corner sets the map's width and height separately, to any shape (a wide map on a wide or 4K screen, say). Off (the default): the map stays square."] = "Das Ziehen der Ecke setzt Breite und Höhe der Karte getrennt, in beliebiger Form (z. B. eine breite Karte auf einem Breitbild- oder 4K-Monitor). Aus (Standard): die Karte bleibt quadratisch."
L["While Lock map position is off, you can also drag the map's bottom-right corner to any width and height."] = "Solange \"Kartenposition sperren\" aus ist, kannst du auch die untere rechte Ecke der Karte auf jede Breite und Höhe ziehen."
L["Show/hide key"] = "Taste zum Anzeigen/Verbergen"
L["Key doesn't show the map in combat"] = "Taste zeigt Karte nicht im Kampf"
L["In combat, pressing the show/hide key doesn't show the map, so a press by mistake can't pop it up mid-fight. It can still hide the map, and a map already showing stays. The minimap button and /agps toggle work as usual."] = "Im Kampf zeigt die Taste die Karte nicht an, damit sie nicht versehentlich mitten im Kampf aufgeht. Verbergen geht weiterhin, und eine schon angezeigte Karte bleibt. Minikartenbutton und /agps toggle funktionieren wie gewohnt."
L["Show distances in"] = "Entfernungen anzeigen in"
L["Yards (the game's)"] = "Yards (wie im Spiel)"
L["Meters and kilometers"] = "Meter und Kilometer"
L["Feet and miles"] = "Fuß und Meilen"
L["Minimap button"] = "Minikartenbutton"
L["The AzerothGPS button on the game's minimap. Without it, /agps opens this window."] = "Der AzerothGPS-Button an der Minikarte des Spiels. Ohne ihn öffnet /agps dieses Fenster."
L["Chat"] = "Chat"
L["Search"] = "Suche"
L["Find NPCs met in several places"] = "NPCs an mehreren Orten finden"
L["NPCs you've talked to in places far apart (a guard, a supplier in every town) are left out of the search. On: they're found too, at the place you met them nearest you."] = "NPCs, mit denen du an weit entfernten Orten gesprochen hast (eine Wache, ein Händler in jedem Ort), werden bei der Suche ausgelassen. An: auch sie werden gefunden, an dem Ort, der dir am nächsten ist."
L["Performance"] = "Leistung"
L["For a slower PC: the same routes, worked out and drawn less often."] = "Für einen langsameren PC: dieselben Routen, seltener berechnet und gezeichnet."
L["Use Low-End Settings"] = "Sparmodus nutzen"
L["Restore Defaults"] = "Standardwerte"
L["Map redraws per second"] = "Kartenaktualisierungen pro Sekunde"
L["The setting that saves the most: at 10 the map needs about half the work it does at 20, and still follows you smoothly. Standing still, it only redraws when something changes."] = "Die Einstellung, die am meisten spart: bei 10 braucht die Karte etwa die Hälfte der Arbeit von 20 und folgt dir trotzdem flüssig. Im Stand zeichnet sie nur neu, wenn sich etwas ändert."
L["Work out a route you've left at most every"] = "Verlassene Route höchstens neu berechnen alle"
L["%d s"] = "%d s"
L["Off the route (fighting, gathering, or going your own way), it's worked out again from where you are. Less often is less work; the route catches up with you a little later."] = "Abseits der Route (Kämpfen, Sammeln oder eigene Wege) wird sie ab deiner Position neu berechnet. Seltener heißt weniger Arbeit; die Route holt dich etwas später ein."
L["Stops routed and drawn ahead"] = "Im Voraus berechnete Halte"
L["How many of the route's stops are worked out and drawn at a time; the next come in as you reach them. Every stop is still in the fastest order and on the map, and the ones further on are listed with an estimated distance until they're routed."] = "Wie viele Halte der Route gleichzeitig berechnet und gezeichnet werden; die nächsten kommen dazu, wenn du sie erreichst. Jeder Halt bleibt in der schnellsten Reihenfolge und auf der Karte, und die weiter entfernten werden mit geschätzter Entfernung gelistet, bis sie berechnet sind."
L["Gentle background work"] = "Schonende Hintergrundarbeit"
L["Walks around obstacles and the road data (after a /reload) are worked out in smaller slices of each frame: fewer stutters on a slow PC. The first route after a /reload, and walks off the roads, take a little longer to appear."] = "Wege um Hindernisse und die Straßendaten (nach einem /reload) werden in kleineren Stücken pro Frame berechnet: weniger Ruckler auf einem langsamen PC. Die erste Route nach einem /reload und Wege abseits der Straßen erscheinen etwas später."
L["Direction arrow"] = "Richtungspfeil"
L["Turn the arrow every frame"] = "Pfeil in jedem Frame drehen"
L["On: the arrow turns with every frame, as smoothly as the game runs. Off: 20 times a second, less work at high frame rates."] = "An: der Pfeil dreht sich in jedem Frame, so flüssig wie das Spiel läuft. Aus: 20-mal pro Sekunde, weniger Arbeit bei hohen Bildraten."
L["Other settings to improve performance"] = "Weitere Einstellungen für bessere Leistung"
L["Fewer icons on the map (Map icons, or the round button at the map's bottom-left): herbs, ore, quests and points of interest; quest areas' outlines off; and a smaller map."] = "Weniger Symbole auf der Karte (Kartensymbole, oder der runde Button unten links an der Karte): Kräuter, Erz, Quests und interessante Orte; Umrisse der Questgebiete aus; und eine kleinere Karte."
L["Map opacity"] = "Kartendeckkraft"
L["Fade the map while moving"] = "Karte beim Laufen ausblenden"
L["While you move, the map fades to the opacity below, leaving the route, the stop markers and your arrow as they are. It comes back a moment after you stop, or right away when you point at the map."] = "Während du dich bewegst, blendet die Karte auf die Deckkraft unten ab; Route, Haltmarkierungen und dein Pfeil bleiben, wie sie sind. Sie kehrt kurz nach dem Anhalten zurück, oder sofort, wenn du auf die Karte zeigst."
L["Map opacity while moving"] = "Kartendeckkraft beim Laufen"
L["Click-through"] = "Durchklicken"
L["Clicks go to the game world (targeting, the camera), not the map or arrow."] = "Klicks gehen an die Spielwelt (Ziel, Kamera), nicht an Karte oder Pfeil."
L["Click-through while moving"] = "Durchklicken beim Laufen"
L["While you move, the map and the direction arrow ignore the mouse, so a click there targets or turns the camera instead. They take clicks again a moment after you stop."] = "Während du dich bewegst, ignorieren Karte und Richtungspfeil die Maus, ein Klick dort wählt also ein Ziel oder dreht die Kamera. Kurz nach dem Anhalten nehmen sie wieder Klicks an."
L["Click-through in combat"] = "Durchklicken im Kampf"
L["In combat, the map and the direction arrow ignore the mouse, so a click there targets or turns the camera instead."] = "Im Kampf ignorieren Karte und Richtungspfeil die Maus, ein Klick dort wählt also ein Ziel oder dreht die Kamera."
L["In combat"] = "Im Kampf"
L["Hide the map"] = "Karte verbergen"
L["Hidden while you're in combat, so nothing on it gets clicked by mistake mid-fight. It comes back when combat ends."] = "Im Kampf verborgen, damit nichts darauf versehentlich angeklickt wird. Sie kehrt nach dem Kampf zurück."
L["Map opacity in combat"] = "Kartendeckkraft im Kampf"
L["Hide the direction arrow"] = "Richtungspfeil verbergen"
L["Hidden while you're in combat. It comes back when combat ends."] = "Im Kampf verborgen. Er kehrt nach dem Kampf zurück."
L["Arrow opacity in combat"] = "Pfeildeckkraft im Kampf"
L["Routing"] = "Routenplanung"
L["Avoid zones too high for your level"] = "Zonen über deiner Stufe meiden"
L["Routes go around zones whose levels are red for your character (their lowest level more than 4 above yours) when there's another way, like the other faction's towns. The zones you start and end in don't count."] = "Routen umgehen Zonen, deren Stufen für deinen Charakter rot sind (niedrigste Stufe mehr als 4 über deiner), wenn es einen anderen Weg gibt, wie bei den Orten der anderen Fraktion. Start- und Zielzone zählen nicht."
L["Use flight paths"] = "Flugrouten nutzen"
L["Routes take flights (connecting ones too) between the flight masters this character knows, when that's faster. The addon learns which ones you know from the flight map: open it once at any flight master."] = "Routen nehmen Flüge (auch mit Umsteigen) zwischen den Flugmeistern, die dieser Charakter kennt, wenn das schneller ist. Das AddOn erfährt aus der Flugkarte, welche du kennst: öffne sie einmal bei einem beliebigen Flugmeister."
L["Quest route: only this zone"] = "Questroute: nur diese Zone"
L["The Quest Route button takes only the quests whose objective or turn-in is in the zone you're in (a city counts as its zone). Off: every quest in your log, anywhere."] = "Der Button \"Questroute\" nimmt nur Quests, deren Ziel oder Abgabe in deiner aktuellen Zone liegt (eine Stadt zählt zu ihrer Zone). Aus: jede Quest in deinem Log, überall."
L["Quest route: only tracked quests"] = "Questroute: nur verfolgte Quests"
L["The Quest Route button takes only the quests you track: the ones Questie's tracker shows when it's on, else the ones ticked to track in the quest log. Off: every quest in your log."] = "Der Button \"Questroute\" nimmt nur Quests, die du verfolgst: die, die Questies Tracker zeigt, wenn er an ist, sonst die im Questlog zum Verfolgen angehakten. Aus: jede Quest in deinem Log."
L["Use hearthstone"] = "Ruhestein nutzen"
L["Routes may start with your Hearthstone (or a shaman's Astral Recall) when it's in your bags, off cooldown, and faster. Home is your inn's town; the exact spot is learned after your first hearth. The directions say when; click the button beside them to use it."] = "Routen dürfen mit deinem Ruhestein (oder dem Astralen Rückruf eines Schamanen) beginnen, wenn er in deinen Taschen ist, keine Abklingzeit hat und schneller ist. Das Zuhause ist der Ort deines Gasthauses; die genaue Stelle wird nach dem ersten Ruhestein gelernt. Die Wegbeschreibung sagt, wann; klick den Button daneben, um ihn zu benutzen."
L["Use class teleports and teleport items"] = "Klassenteleports und Teleportgegenstände nutzen"
L["Routes may start with a mage's teleport (with a Rune of Teleportation), Teleport: Moonglade, or an engineer's Dimensional Ripper - Everlook or Ultrasafe Transporter: Gadgetzan (with the specialization it needs) when it's known or in your bags, off cooldown, and faster. Click the button beside the directions to use it."] = "Routen dürfen mit einem Magierteleport (mit einer Rune der Teleportation), Teleportieren: Mondlichtung oder dem Dimensionszerreißer - Ewige Warte bzw. Ultrasicheren Transporter: Gadgetzan eines Ingenieurs (mit der nötigen Spezialisierung) beginnen, wenn bekannt bzw. in den Taschen, ohne Abklingzeit und schneller. Klick den Button neben der Wegbeschreibung, um ihn zu benutzen."
L["Avoid the other faction's towns"] = "Orte der anderen Fraktion meiden"
L["Routes keep away from the other faction's guards (their towns and camps, and where their guards patrol), going around when there's a way. A stop inside one is still reached, the shortest way in."] = "Routen halten sich von den Wachen der anderen Fraktion fern (ihre Orte und Lager und wo ihre Wachen patrouillieren) und gehen außen herum, wenn möglich. Ein Halt darin wird trotzdem erreicht, auf dem kürzesten Weg hinein."
L["Road tolerance"] = "Straßentoleranz"
L["0 (as AzerothGPS chooses)"] = "0 (wie AzerothGPS es wählt)"
L["Below 0, routes keep to the roads more and more; above 0, they cut straight across open ground more and more, at the top as if the roads weren't there."] = "Unter 0 bleiben Routen immer mehr auf den Straßen; über 0 kürzen sie immer mehr querfeldein ab, ganz oben, als gäbe es keine Straßen."
L["Visit stops in the fastest order"] = "Halte in schnellster Reihenfolge"
L["Routes with several stops visit them in the fastest order instead of the order you placed them. (Double-click the map to place stops.)"] = "Routen mit mehreren Halten besuchen sie in der schnellsten Reihenfolge statt in der, in der du sie gesetzt hast. (Doppelklick auf die Karte setzt Halte.)"
L["Except in cities"] = "Außer in Städten"
L["Stops down in a city (Undercity) are visited in the order you placed them among themselves: how you want to go around a city is up to you. Stops outside the city still go in the fastest order. (A quest route is always put in the fastest order.)"] = "Halte unten in einer Stadt (Unterstadt) werden untereinander in deiner Reihenfolge besucht: wie du durch eine Stadt gehst, entscheidest du. Halte außerhalb der Stadt kommen weiterhin in schnellster Reihenfolge. (Eine Questroute wird immer in die schnellste Reihenfolge gebracht.)"
L["X on the route panel cancels the route"] = "X an der Routenleiste bricht Route ab"
L["The X at the top right of the map's route panel (the steps) cancels the whole route. Off: it only closes the panel until the route changes, and the route goes on."] = "Das X oben rechts an der Routenleiste der Karte (die Schritte) bricht die ganze Route ab. Aus: es schließt nur die Leiste, bis sich die Route ändert, und die Route läuft weiter."
L["Zeppelins, boats and the tram"] = "Zeppeline, Schiffe und die Bahn"
L["Unticked ones are never used in routes. Right-clicking a dock on the map does the same."] = "Nicht angekreuzte werden nie in Routen genutzt. Ein Rechtsklick auf einen Anleger auf der Karte bewirkt dasselbe."
L["Zeppelins"] = "Zeppeline"
L["Routes may take the zeppelin between %s and %s. Unticked: never."] = "Routen dürfen den Zeppelin zwischen %s und %s nehmen. Nicht angekreuzt: nie."
L["Boats"] = "Schiffe"
L["Routes may take the boat between %s and %s. Unticked: never."] = "Routen dürfen das Schiff zwischen %s und %s nehmen. Nicht angekreuzt: nie."
L["The Deeprun Tram"] = "Die Tiefenbahn"
L["Routes may take the Deeprun Tram between %s and %s. Unticked: never."] = "Routen dürfen die Tiefenbahn zwischen %s und %s nehmen. Nicht angekreuzt: nie."
L["Waypoints and sharing"] = "Wegpunkte und Teilen"
L["Accept TomTom /way commands"] = "TomTom-/way-Befehle annehmen"
L["/way lines typed or pasted in chat add stops to the route (several pasted lines at once become several stops). With TomTom installed, its waypoint is set too. Questie's \"Set TomTom Target\" adds a stop the same way."] = "Im Chat eingegebene oder eingefügte /way-Zeilen fügen der Route Halte hinzu (mehrere eingefügte Zeilen werden mehrere Halte). Mit installiertem TomTom wird auch dessen Wegpunkt gesetzt. Questies \"Set TomTom Target\" fügt ebenso einen Halt hinzu."
L["Questie: no map for that target"] = "Questie: keine Karte für dieses Ziel"
L["%s is already on your route."] = "%s ist schon auf deiner Route."
L["Map pin links add stops"] = "Kartenmarkierungslinks setzen Halte"
L["Clicking a map pin someone posted in chat (\"[Map Pin Location]\") adds a stop there. To share a spot yourself, Ctrl + left-click it on the map for the map pin (a diamond, the game's own waypoint), then Shift + left-click the pin; Ctrl + left-click it again removes it."] = "Ein Klick auf eine Kartenmarkierung, die jemand im Chat gepostet hat (\"[Kartenmarkierung]\"), setzt dort einen Halt. Um selbst einen Ort zu teilen: Strg + Linksklick auf der Karte setzt die Kartenmarkierung (eine Raute, der Wegpunkt des Spiels), dann Umschalt + Linksklick auf die Markierung; erneut Strg + Linksklick entfernt sie."
L["Accept routes shared by players"] = "Von Spielern geteilte Routen annehmen"
L["Route links other AzerothGPS users post in chat (\"[AzerothGPS Route: 3 stops]\", from the Import and Share window) can be clicked to get their route. Nothing comes in unless you click one, and you're asked before it replaces yours."] = "Routenlinks, die andere AzerothGPS-Nutzer im Chat posten (\"[AzerothGPS-Route: 3 Halte]\", aus dem Fenster \"Importieren und Teilen\"), lassen sich anklicken, um ihre Route zu bekommen. Nichts kommt an, ohne dass du klickst, und du wirst gefragt, bevor sie deine ersetzt."
L["Import and Share..."] = "Importieren und Teilen..."
L["Directions"] = "Wegbeschreibung"
L["Show direction arrow"] = "Richtungspfeil anzeigen"
L["Two small panels (TomTom style): an arrow along the route, and beside it the directions: the next turn (\"Turn left 120 yd, toward Razor Hill\"), the stop's distance and ETA, and the stops after it when made taller."] = "Zwei kleine Leisten (im TomTom-Stil): ein Pfeil entlang der Route und daneben die Wegbeschreibung: das nächste Abbiegen (\"In 120 yd links abbiegen, Richtung Klingenhügel\"), Entfernung und Ankunftszeit des Halts und, wenn höher gezogen, die folgenden Halte."
L["Lock arrow position"] = "Pfeilposition sperren"
L["Lock directions text position"] = "Position des Wegbeschreibungstexts sperren"
L["Locks the directions text in place, apart from the arrow. Unlocked: drag it to move it and its bottom-right corner to resize it (taller lists the later stops). With no route it shows a placeholder while unlocked, so you can place it. Locked, clicks pass through it to the game world."] = "Sperrt den Wegbeschreibungstext an seinem Platz, getrennt vom Pfeil. Entsperrt: zum Verschieben ziehen, die untere rechte Ecke ändert die Größe (höher gezogen listet er spätere Halte). Ohne Route zeigt er entsperrt einen Platzhalter, damit du ihn platzieren kannst. Gesperrt gehen Klicks durch ihn hindurch in die Spielwelt."
L["Locks the arrow in place. Unlocked: drag it to move it. Snapped to the directions text, it still moves with the text while the text is unlocked. With no route it shows a placeholder while unlocked, so you can place it. Locked, clicks pass through it to the game world."] = "Sperrt den Pfeil an seinem Platz. Entsperrt: zum Verschieben ziehen. An den Wegbeschreibungstext angedockt, bewegt er sich mit dem Text, solange der Text entsperrt ist. Ohne Route zeigt er entsperrt einen Platzhalter, damit du ihn platzieren kannst. Gesperrt gehen Klicks durch ihn hindurch in die Spielwelt."
L["Questing objective tracker"] = "Questziel-Verfolgung"
L["A stop inside a quest's area (the blue outlines, for quests in your log) is done when that quest's objectives are, not when you get there. In the area, the route waits and the arrow shows a ! and the objective counters. Leave before they're done and the route leads back; then it goes on to the next stop."] = "Ein Halt in einem Questgebiet (die blauen Umrisse, für Quests in deinem Log) ist erledigt, wenn die Questziele erfüllt sind, nicht beim Ankommen. Im Gebiet wartet die Route, und der Pfeil zeigt ein ! und die Zielzähler. Gehst du vorher weg, führt die Route zurück; danach geht es zum nächsten Halt."
L["Arrow size"] = "Pfeilgröße"
L["%d px"] = "%d px"
L["Arrow background"] = "Pfeilhintergrund"
L["Show the directions text"] = "Wegbeschreibungstext anzeigen"
L["The panel beside the arrow with the next turn, the stop's distance and ETA and the stops after it. Off: the arrow alone, without the text."] = "Die Leiste neben dem Pfeil mit dem nächsten Abbiegen, Entfernung und Ankunftszeit des Halts und den folgenden Halten. Aus: nur der Pfeil, ohne den Text."
L["List the stops only"] = "Nur Halte auflisten"
L["The directions list the route's stops, each with its distance and ETA, without the turns (\"Continue straight, then turn left in 280 yd\")."] = "Die Wegbeschreibung listet die Halte der Route, jeweils mit Entfernung und Ankunftszeit, ohne Abbiegehinweise (\"Geradeaus weiter, dann in 280 yd links abbiegen\")."
L["Text size"] = "Textgröße"
L["Directions background"] = "Hintergrund der Wegbeschreibung"
L["Snap the arrow to the directions"] = "Pfeil an Wegbeschreibung andocken"
L["The arrow sits against a side of the directions and the two move as one: drag the directions to move both. Unlocked, drag the arrow away to move it on its own, and drop it against a side of the directions to snap it there again."] = "Der Pfeil sitzt an einer Seite der Wegbeschreibung, und beide bewegen sich zusammen: zieh die Wegbeschreibung, um beide zu verschieben. Entsperrt: zieh den Pfeil weg, um ihn allein zu verschieben, und lass ihn an einer Seite der Wegbeschreibung fallen, um ihn wieder anzudocken."
L["Arrow side"] = "Pfeilseite"
L["Left"] = "Links"
L["Right"] = "Rechts"
L["Above"] = "Oben"
L["Below"] = "Unten"
L["Hide"] = "Ausblenden"
L["No arrow: the directions text alone. The arrow's place shows a hearthstone or teleport to use when the route starts with one."] = "Kein Pfeil: nur der Text der Wegbeschreibung. Beginnt die Route mit einem Ruhestein oder Teleport, erscheint er zum Benutzen an der Stelle des Pfeils."
L["How it works"] = "So funktioniert es"
L["The arrow points along the route: |cff73ff73green|r straight ahead, |cffffffffwhite|r for a turn coming up, |cffff7359red|r when the route is behind you. On a flight it shows where you land and when."] = "Der Pfeil zeigt entlang der Route: |cff73ff73grün|r geradeaus, |cffffffffweiß|r bei einem kommenden Abbiegen, |cffff7359rot|r, wenn die Route hinter dir liegt. Auf einem Flug zeigt er, wo und wann du landest."
L["The directions' lines: the next turn and its distance, the road or place you're heading toward, the stop with its distance and ETA, then the turn after that. With List the stops only, just the stops."] = "Die Zeilen der Wegbeschreibung: das nächste Abbiegen und seine Entfernung, die Straße oder der Ort, auf den du zusteuerst, der Halt mit Entfernung und Ankunftszeit, dann das übernächste Abbiegen. Mit \"Nur Halte auflisten\" nur die Halte."
L["Each has its own lock: untick Lock arrow position or Lock directions text position, then drag that one; drag the directions' bottom-right corner to resize them. Made taller, they list the later stops too. Unlocked with no route, they show a placeholder so you can place them."] = "Jedes hat seine eigene Sperre: Pfeilposition sperren oder Position des Wegbeschreibungstexts sperren abwählen und das jeweilige ziehen; die untere rechte Ecke der Wegbeschreibung ändert die Größe. Höher gezogen listen sie auch spätere Halte. Entsperrt ohne Route zeigen sie einen Platzhalter, damit du sie platzieren kannst."
L["Drag the arrow off the directions to move it on its own; drop it against any side of them and it snaps there. Dragging the directions takes a snapped arrow along."] = "Zieh den Pfeil von der Wegbeschreibung weg, um ihn allein zu verschieben; lass ihn an einer ihrer Seiten fallen, dann dockt er dort an. Beim Ziehen der Wegbeschreibung kommt ein angedockter Pfeil mit."
L["Only the text: pick Hide under Arrow side. Only the arrow: untick Show the directions text."] = "Nur der Text: unter Pfeilseite Ausblenden wählen. Nur der Pfeil: Wegbeschreibungstext anzeigen abwählen."
L["In a quest's area the arrow shows a ! and the directions the quest's objectives. A small Sprint icon pulsing in the directions' top-right corner means you picked up or finished a quest after making your quest route: click it (or the quest route button on the map) to make the route again with it or its turn-in."] = "In einem Questgebiet zeigt der Pfeil ein ! und die Wegbeschreibung die Questziele. Ein kleines pulsierendes Sprinten-Symbol oben rechts in der Wegbeschreibung bedeutet, dass du nach dem Erstellen deiner Questroute eine Quest angenommen oder abgeschlossen hast: klick es an (oder den Questroute-Button auf der Karte), um die Route mit ihr oder ihrer Abgabe neu zu erstellen."
L["Map style and layers: the round button at the map's bottom-left."] = "Kartenstil und Ebenen: der runde Button unten links an der Karte."
L["Right-click opens the world map"] = "Rechtsklick öffnet die Weltkarte"
L["In the OpenMap style, right-click zooms out a few steps on the same spot (each right-click a few more, up to the whole world). In the Terrain style, it shows Azeroth: click a continent, then a spot on it, to come back to the terrain view there. Right-click again goes back."] = "Im Stil OpenMap zoomt Rechtsklick an derselben Stelle ein paar Stufen heraus (jeder Rechtsklick ein paar mehr, bis zur ganzen Welt). Im Stil Gelände zeigt er Azeroth: klick einen Kontinent und dann eine Stelle darauf an, um dort zur Geländeansicht zurückzukehren. Ein erneuter Rechtsklick geht zurück."
L["Building interiors"] = "Gebäudeinneres"
L["Inside buildings and caves (e.g. Undercity), the terrain view shows the building's own map, like the minimap."] = "In Gebäuden und Höhlen (z. B. Unterstadt) zeigt die Geländeansicht die eigene Karte des Gebäudes, wie die Minikarte."
L["Map style"] = "Kartenstil"
L["OpenMap (the default): the ground seen from above, and the mouse wheel zooms on out past the land, through zones and continents to the whole world on a stitched world map, and back in to the roads. Right-click zooms out a few steps on the same spot, up to the whole world. Picked again after another style, it loads once the UI is reloaded (a prompt offers it); in the other styles nothing of it is loaded."] = "OpenMap (Standard): das Gelände von oben gesehen; das Mausrad zoomt über das Land hinaus durch Zonen und Kontinente bis zur ganzen Welt auf einer zusammengesetzten Weltkarte und wieder hinein bis zu den Straßen. Rechtsklick zoomt an derselben Stelle ein paar Stufen heraus, bis zur ganzen Welt. Nach einem anderen Stil erneut gewählt, wird es nach dem Neuladen der Benutzeroberfläche geladen (eine Abfrage bietet es an); in den anderen Stilen wird nichts davon geladen."
L["Terrain: the ground alone, as far out as the land. World Map: the world map, fully explored. No Spoiler Map: the world map as your character has explored it."] = "Gelände: nur der Boden, so weit das Land reicht. Weltkarte: die Weltkarte, vollständig erkundet. Spoilerfreie Karte: die Weltkarte, so wie dein Charakter sie erkundet hat."
L["Show only explored areas"] = "Nur erkundete Gebiete zeigen"
L["The OpenMap style's zone art shows only the areas this character has explored, as the game's own world map does; the rest is the zone's blank parchment. The terrain close in is never changed."] = "Die Zonengrafik im Stil OpenMap zeigt nur die Gebiete, die dieser Charakter erkundet hat, wie die Weltkarte des Spiels; der Rest ist das leere Pergament der Zone. Das Gelände aus der Nähe wird nie verändert."
L["Double-click one to add it as a stop."] = "Doppelklick fügt es als Halt hinzu."
L["Flight masters"] = "Flugmeister"
L["Green: known. Gray: not learned. Yellow: open a flight map once so the addon can tell."] = "Grün: bekannt. Grau: nicht erlernt. Gelb: öffne einmal eine Flugkarte, damit das AddOn es erkennt."
L["Points of interest"] = "Interessante Orte"
L["Places marked on the world map."] = "Auf der Weltkarte markierte Orte."
L["Place names"] = "Ortsnamen"
L["Town and area names, when zoomed in."] = "Orts- und Gebietsnamen, wenn hineingezoomt."
L["Your quests' objectives and turn-ins."] = "Ziele und Abgaben deiner Quests."
L["Party members"] = "Gruppenmitglieder"
L["Your party's or raid's members, as round icons of their class in their class's color (their name when you point at one), where the game gives their position. They don't need AzerothGPS themselves."] = "Die Mitglieder deiner Gruppe oder deines Schlachtzugs als runde Klassensymbole in ihrer Klassenfarbe (der Name beim Daraufzeigen), wo das Spiel ihre Position liefert. Sie selbst brauchen kein AzerothGPS."
L["Route on the minimap"] = "Route auf der Minikarte"
L["Your route on the game's minimap too, around you, and the next stop's marker (on the minimap's edge while it's further). It's drawn again only when something on it changes."] = "Deine Route auch auf der Minikarte des Spiels, um dich herum, und die Markierung des nächsten Halts (am Rand der Minikarte, solange er weiter weg ist). Sie wird nur neu gezeichnet, wenn sich etwas daran ändert."
L["Icons on the minimap"] = "Symbole auf der Minikarte"
L["The map's icons on the game's minimap too: your pins, the herbs and ore you know, city places, party members, docks and entrances, each when it's shown on the map. Off by default."] = "Die Symbole der Karte auch auf der Minikarte des Spiels: deine Pins, bekannte Kräuter und Erze, Orte in Städten, Gruppenmitglieder, Anleger und Eingänge, jeweils wenn sie auf der Karte angezeigt werden. Standardmäßig aus."
L["Minimap shape"] = "Form der Minikarte"
L["Automatic"] = "Automatisch"
L["What your minimap addon says, or the shape it gives the minimap."] = "Was dein Minikarten-AddOn angibt, oder die Form, die es der Minikarte gibt."
L["Round"] = "Rund"
L["Square"] = "Eckig"
L["Quest areas on the map"] = "Questgebiete auf der Karte"
L["Quest areas on the minimap"] = "Questgebiete auf der Minikarte"
L["Our outlines of your quests' objective areas on the GPS map as your minimap. Off: the game's own quest areas there instead."] = "Unsere Umrisse der Zielgebiete deiner Quests auf der GPS-Karte als Minikarte. Aus: stattdessen die Questgebiete des Spiels."
L["Outlines of your quests' objective areas, like on the minimap. Hover one to see the quest's objectives."] = "Umrisse der Zielgebiete deiner Quests, wie auf der Minikarte. Zeig auf eines, um die Questziele zu sehen."
L["Herbs you've gathered, hovered on the game minimap, right-clicked (without Herbalism) or imported. Saved for all your characters. A farming area (map menu) uses the kinds shown."] = "Kräuter, die du gesammelt, auf der Minikarte des Spiels überfahren, rechtsgeklickt (ohne Kräuterkunde) oder importiert hast. Für alle deine Charaktere gespeichert. Ein Farmgebiet (Kartenmenü) nutzt die angezeigten Arten."
L["Mining nodes you've gathered, hovered on the game minimap, right-clicked (without Mining) or imported. Saved for all your characters. A farming area (map menu) uses the kinds shown."] = "Erzvorkommen, die du abgebaut, auf der Minikarte des Spiels überfahren, rechtsgeklickt (ohne Bergbau) oder importiert hast. Für alle deine Charaktere gespeichert. Ein Farmgebiet (Kartenmenü) nutzt die angezeigten Arten."
L["Dungeons and raids"] = "Dungeons und Schlachtzüge"
L["Their entrances, on every map style. Click one for its map, with its bosses in the usual order; right-click goes back out."] = "Ihre Eingänge, in jedem Kartenstil. Klick auf einen zeigt seine Karte mit den Bossen in der üblichen Reihenfolge; Rechtsklick geht wieder hinaus."
L["Cave entrances"] = "Höhleneingänge"
L["The ways into caves and mines (not on a continent's map). Double-click one for a stop there."] = "Die Eingänge zu Höhlen und Minen (nicht auf der Kontinentkarte). Doppelklick auf einen setzt dort einen Halt."
L["Your pins (Shift + left-click on the map: Options > Tools) and the ones shared with everyone. Double-click one for a stop there; right-click to remove it."] = "Deine Pins (Umschalt + Linksklick auf die Karte: Optionen > Werkzeuge) und die mit allen geteilten. Doppelklick auf einen setzt dort einen Halt; Rechtsklick entfernt ihn."
L["Frame color"] = "Rahmenfarbe"
L["AzerothGPS's own"] = "Die von AzerothGPS"
L["Buttons"] = "Buttons"
L["The game's own"] = "Die des Spiels"
L["Match the frame"] = "Wie der Rahmen"
L["The frame color's (above)."] = "Die der Rahmenfarbe (oben)."
L["Close button (X)"] = "Schließen-Button (X)"
L["Same as the buttons"] = "Wie die Buttons"
L["Route color"] = "Routenfarbe"
L["Rainbow"] = "Regenbogen"
L["The colors of the rainbow along the route."] = "Die Farben des Regenbogens entlang der Route."
L["A little celebration over the map when you reach your trip's last stop."] = "Eine kleine Feier über der Karte, wenn du den letzten Halt deiner Reise erreichst."
L["None"] = "Keine"
L["Celebration"] = "Feier"
L["Try It"] = "Testen"
L["Charm"] = "Anhänger"
L["A legendary weapon hanging on a string from the AzerothGPS logo."] = "Eine legendäre Waffe, die an einer Schnur am AzerothGPS-Logo hängt."
L["Swings while you move"] = "Schwingt beim Laufen"
L["Turning swings it out of the turn and the road jostles it; it twists on its string and settles when you stop. Off: it hangs still, facing you."] = "In Kurven schwingt sie nach außen, und der Weg schüttelt sie; sie dreht sich an ihrer Schnur und kommt zur Ruhe, wenn du anhältst. Aus: sie hängt still und zeigt zu dir."
L["Keys and buttons"] = "Tasten und Buttons"
L["Keys"] = "Tasten"
L["Where each one goes"] = "Wo jeder hinkommt"
L["Always shown: next to the map button, going up or to the right. In the menu: slides out past those when you click the map button (it closes after 20 seconds untouched). Hidden: not on the map (the setting still works). A group (map style, quests, herbs and ore) is one button: click it and its buttons slide out beside it. ^ and v set the order."] = "Immer sichtbar: neben dem Kartenbutton, nach oben oder nach rechts. Im Menü: fährt dahinter aus, wenn du den Kartenbutton klickst (schließt nach 20 Sekunden ohne Benutzung). Verborgen: nicht auf der Karte (die Einstellung wirkt trotzdem). Eine Gruppe (Kartenstil, Quests, Kräuter und Erz) ist ein Button: klick ihn an, und seine Buttons fahren daneben aus. ^ und v legen die Reihenfolge fest."
L["At the map's size: %d fit going up and %d going right (always shown and in the menu together)."] = "Bei dieser Kartengröße passen %d nach oben und %d nach rechts (immer sichtbar und im Menü zusammen)."
L["Always shown"] = "Immer sichtbar"
L["In the menu"] = "Im Menü"
L["Up"] = "Hoch"
L["Hidden"] = "Aus"
L["On"] = "An"
L["Earlier (nearer the map button)"] = "Früher (näher am Kartenbutton)"
L["Later (further from the map button)"] = "Später (weiter vom Kartenbutton)"
L["A group: %s."] = "Eine Gruppe: %s."
L["No room for %s there at this map size (it would need %s). Make the map bigger (Map window: %s), or move or hide another one."] = "Kein Platz für %s bei dieser Kartengröße (bräuchte %s). Vergrößere die Karte (Kartenfenster: %s) oder verschiebe bzw. verberge einen anderen."
L["Height and Width"] = "Höhe und Breite"
L["Tools"] = "Werkzeuge"
L["Your own marks on the map: a name and an icon."] = "Deine eigenen Markierungen auf der Karte: ein Name und ein Symbol."
L["Shift + left-click on the map, then |cffffd100Create Pin|r: name it, pick an icon (any the game has, as for a macro) and, where floors lie over each other (a dungeon, Undercity, a cave), its floor. Double-click a pin for a stop there; right-click it to remove it. Pins are shared with your map data (Copy Map Data..., Help improve)."] = "Umschalt + Linksklick auf die Karte, dann |cffffd100Pin erstellen|r: gib ihm einen Namen, wähle ein Symbol (jedes des Spiels, wie bei einem Makro) und, wo Etagen übereinanderliegen (ein Dungeon, Unterstadt, eine Höhle), seine Etage. Doppelklick auf einen Pin setzt dort einen Halt; Rechtsklick entfernt ihn. Pins werden mit deinen Kartendaten geteilt (Kartendaten kopieren..., Mithelfen)."
L["Pinning"] = "Pins setzen"
L["Shift + left-click on the map asks to create a pin there. Off: Shift + left-drag only moves the map's window."] = "Umschalt + Linksklick auf die Karte fragt, ob dort ein Pin erstellt werden soll. Aus: Umschalt + Linksziehen verschiebt nur das Kartenfenster."
L["Help improve AzerothGPS"] = "AzerothGPS verbessern helfen"
L["Kept on your PC only; sharing it is a separate step."] = "Nur auf deinem PC gespeichert; das Teilen ist ein eigener Schritt."
L["How to share..."] = "So teilst du..."
L["Type |cffffd100/reload|r before |cffffd100Copy Map Data...|r: it saves all your road and wall edits and pins, so every one of them is in the copy."] = "Gib vor |cffffd100Kartendaten kopieren...|r |cffffd100/reload|r ein: das speichert alle Straßen- und Maueränderungen und Pins, damit jede davon in der Kopie ist."
L["What Copy Map Data... includes"] = "Was \"Kartendaten kopieren...\" enthält"
L["Untick what you'd rather keep to yourself: it's left out of the copy."] = "Wähle ab, was du lieber für dich behältst: es wird nicht kopiert."
L["%s Unticked: left out of the copy."] = "%s Nicht angekreuzt: wird nicht kopiert."
L["Waiting to be shared: %s, %s, %s, %s"] = "Warten aufs Teilen: %s, %s, %s, %s"
L["%d road"] = "%d Straße"
L["%d wall"] = "%d Mauer"
L["%d pin"] = "%d Pin"
L["%d trip"] = "%d Weg"
L["%d trips"] = "%d Wege"
L["Thanks"] = "Danke"
L["%s options failed:"] = "%s-Optionen fehlgeschlagen:"
L["Reset to defaults"] = "Auf Standard zurücksetzen"
L["Left-click: show/hide the GPS"] = "Linksklick: GPS anzeigen/verbergen"
L["Right-click: options"] = "Rechtsklick: Optionen"
L["Drag: move this button"] = "Ziehen: diesen Button verschieben"
L["Car-GPS style map and navigation. Settings are in the AzerothGPS window."] = "Karte und Navigation im Stil eines Auto-Navis. Die Einstellungen sind im AzerothGPS-Fenster."
L["Open AzerothGPS options"] = "AzerothGPS-Optionen öffnen"
L["Name"] = "Name"
L["Choose an icon:"] = "Wähle ein Symbol:"
L["Saved at logout or /reload"] = "Beim Ausloggen oder /reload gespeichert"
L["Floor: %s"] = "Etage: %s"
L["Floor: every floor here"] = "Etage: alle Etagen hier"
L["Icons %d-%d of %d (mouse wheel scrolls)"] = "Symbole %d-%d von %d (Mausrad scrollt)"
L["pinned %s (double-click it for a stop, right-click to remove it)"] = "%s angepinnt (Doppelklick für einen Halt, Rechtsklick zum Entfernen)"
L["%d of your drawn roads and walls are in the map data now (kept in your saved data)"] = "%d deiner gezeichneten Straßen und Mauern sind jetzt in den Kartendaten (in deinen gespeicherten Daten behalten)"
L["recorded %d flight nodes for map %d"] = "%d Flugpunkte für Karte %d aufgezeichnet"
L["flight %s took %.0fs"] = "Flug %s dauerte %.0f s"
