-- The tutorial (Tutorial.lua), 1.2.0
L["Example stop"] = "Beispielhalt"
L["Example quest %d"] = "Beispielquest %d"
L["With the GPS map as your minimap, a double-click on the logo sends the map back to its corner instead."] = "Mit der GPS-Karte als Minikarte schickt ein Doppelklick auf das Logo die Karte stattdessen zurück in ihre Ecke."
L["The GPS map as your minimap"] = "Die GPS-Karte als Minikarte"
L["Minimap replacement"] = "Ersatz für die Minikarte"
L["The GPS map now sits where your minimap was. The game's own icons still show on it."] = "Die GPS-Karte sitzt jetzt dort, wo deine Minikarte war. Die Symbole des Spiels erscheinen weiterhin darauf."
L["Open the GPS map"] = "GPS-Karte öffnen"
L["Click the logo on the minimap's bottom left corner."] = "Klick auf das Logo in der linken unteren Ecke der Minikarte."
L["Auto close on inactivity"] = "Schließt sich bei Inaktivität"
L["Left alone for 5 seconds, the map goes back to its corner. The arrow button on the bottom left, or double-click on the logo, sends it back now."] = "Nach 5 Sekunden ohne Eingabe kehrt die Karte in ihre Ecke zurück. Der Pfeilbutton unten links oder ein Doppelklick auf das Logo schickt sie sofort zurück."
L["Close on movement"] = "Schließen bei Bewegung"
L["That option is on for this demo: take a step and the map goes back to the minimap position."] = "Diese Option ist für diese Demo an: Mach einen Schritt und die Karte kehrt an die Stelle der Minikarte zurück."
L["Close on combat"] = "Schließen im Kampf"
L["It can also go back when combat starts. Both options are in Options > Map."] = "Sie kann auch zurückkehren, wenn ein Kampf beginnt. Beide Optionen stehen unter Optionen > Karte."
L["Three size choices"] = "Drei Größen zur Wahl"
L["Pick the size you like."] = "Wähle die Größe, die dir gefällt."
L["Options on the logo"] = "Optionen am Logo"
L["Right-click the logo in the bottom left of the minimap to open the options panel."] = "Rechtsklick auf das Logo unten links an der Minikarte öffnet das Optionsfenster."
L["Keep the GPS map as your minimap?"] = "GPS-Karte als Minikarte behalten?"
L["You already use the GPS map as your minimap, so it stays on."] = "Du nutzt die GPS-Karte bereits als Minikarte, also bleibt sie an."
L["Yes keeps it on after the tutorial. Everything else goes back to how you had it."] = "Mit Ja bleibt sie nach dem Tutorial an. Alles andere wird wieder so, wie du es hattest."
L["Set a route"] = "Route festlegen"
L["Place a stop"] = "Halt setzen"
L["Double-click anywhere on the map to place a stop."] = "Doppelklick irgendwo auf die Karte setzt einen Halt."
L["Start the route"] = "Route starten"
L["Click Confirm Route. It also starts by itself after 5 seconds of no further map activity."] = "Klick auf Route bestätigen. Nach 5 Sekunden ohne weitere Aktivität auf der Karte startet sie auch von selbst."
L["Add more stops"] = "Weitere Halte hinzufügen"
L["Double-click two more places on the map. Each is added to the route."] = "Doppelklick auf zwei weitere Orte auf der Karte. Jeder wird zur Route hinzugefügt."
L["The fastest order"] = "Die schnellste Reihenfolge"
L["With several stops, the route visits them in the fastest order. Right-click a stop's marker to remove it."] = "Bei mehreren Halten besucht die Route sie in der schnellsten Reihenfolge. Rechtsklick auf die Markierung eines Halts entfernt ihn."
L["Across to another continent"] = "Auf einen anderen Kontinent"
L["This example goes to the other continent. The steps are listed at the top of the map window."] = "Dieses Beispiel führt zum anderen Kontinent. Die Schritte stehen oben im Kartenfenster."
L["Clear a route"] = "Eine Route löschen"
L["Click the X at the top right of the directions to end the route."] = "Klicke auf das X oben rechts in der Wegbeschreibung, um die Route zu beenden."
L["Herbs and ore"] = "Kräuter und Erz"
L["Example herbs and ore"] = "Beispiele für Kräuter und Erz"
L["These icons are examples for the tutorial. Yours appear as you gather, and you can import more."] = "Diese Symbole sind Beispiele für das Tutorial. Deine erscheinen beim Sammeln, und du kannst weitere importieren."
L["Show or hide them"] = "Ein- oder ausblenden"
L["The Herbs and Ore buttons in the map menu show or hide them. Find Herbs and Ore shows only the ones you pick."] = "Die Buttons Kräuter und Erz im Kartenmenü blenden sie ein oder aus. Kräuter und Erz finden zeigt nur die, die du auswählst."
L["Draw a farming area"] = "Farmgebiet zeichnen"
L["Click Draw a Farming Area in the map menu, under Herbs, Ore and Farming."] = "Klick im Kartenmenü unter Kräuter, Erz und Farmen auf Farmgebiet zeichnen."
L["Circle the icons"] = "Symbole einkreisen"
L["Drag a loop around the example icons."] = "Zieh eine Schleife um die Beispielsymbole."
L["A loop route"] = "Eine Rundroute"
L["The route visits every one you circled until you reach them."] = "Die Route besucht alle, die du eingekreist hast, bis du sie erreicht hast."
L["Open the search"] = "Suche öffnen"
L["Click the magnifier, Search Places, in the map menu."] = "Klick im Kartenmenü auf die Lupe, Orte suchen."
L["Find your class trainer"] = "Finde deinen Klassenlehrer"
L["Type this in the search box: %s"] = "Gib das ins Suchfeld ein: %s"
L["Pick a result"] = "Ergebnis wählen"
L["Click a result, or press Enter for the first one: it becomes a stop."] = "Klick auf ein Ergebnis oder drück die Eingabetaste für das erste: es wird ein Halt."
L["More to find"] = "Noch mehr zu finden"
L["The search also finds flight masters, inns, towns and zones. Type what you need and get a route to it."] = "Die Suche findet auch Flugmeister, Gasthäuser, Orte und Zonen. Gib ein, was du brauchst, und erhalte eine Route dorthin."
L["Dungeon maps"] = "Dungeonkarten"
L["A dungeon's map"] = "Die Karte eines Dungeons"
L["This is the map of %s. Click a dungeon's entrance on the map to open its map like this."] = "Das ist die Karte von %s. Klick auf der Karte auf einen Dungeoneingang, um seine Karte so zu öffnen."
L["Bosses in order"] = "Bosse der Reihe nach"
L["The bosses are numbered in the usual order, with the usual path between them. You can mark off bosses and manually position yourself (when in a dungeon) with a double click."] = "Die Bosse sind in der üblichen Reihenfolge nummeriert, mit dem üblichen Weg dazwischen. Mit einem Doppelklick kannst du Bosse abhaken und (im Dungeon) deine Position selbst setzen."
L["Back out"] = "Wieder hinaus"
L["Right-click the map to leave a dungeon's map. The tutorial has done it for you."] = "Rechtsklick auf die Karte verlässt eine Dungeonkarte. Das Tutorial hat das für dich erledigt."
L["A route through your quests"] = "Eine Route durch deine Quests"
L["Click Quest Route in the map menu."] = "Klick im Kartenmenü auf Questroute."
L["You have no quests with known places right now, so these stops are examples."] = "Du hast gerade keine Quests mit bekannten Orten, daher sind diese Halte Beispiele."
L["What it does"] = "Was sie macht"
L["It visits your quests' objectives in the fastest order, then the turn-ins. A stop is done when its quest is, not when you get there. Right-click the button to choose how it routes."] = "Sie besucht die Ziele deiner Quests in der schnellsten Reihenfolge, dann die Abgaben. Ein Halt ist erledigt, wenn seine Quest es ist, nicht wenn du ankommst. Rechtsklick auf die Schaltfläche, um die Routenart zu wählen."
L["With your other addons"] = "Mit deinen anderen Addons"
L["AzerothGPS also works with: %s."] = "AzerothGPS funktioniert auch mit: %s."
L["The direction arrow"] = "Der Richtungspfeil"
L["The arrow and the directions"] = "Pfeil und Wegbeschreibung"
L["Move it"] = "Verschieben"
L["Drag the directions panel: the arrow comes with it."] = "Zieh die Wegbeschreibungsleiste: der Pfeil kommt mit."
L["Pull them apart"] = "Auseinanderziehen"
L["Drag the arrow off the panel to place it on its own. Drop it on a side of the panel to snap it back."] = "Zieh den Pfeil von der Leiste weg, um ihn einzeln zu platzieren. Lass ihn an einer Seite der Leiste los, um ihn wieder anzudocken."
L["Size and lock"] = "Größe und Sperre"
L["The map window"] = "Das Kartenfenster"
L["Double-click the logo at the map's top left. The map hides and only the logo stays."] = "Doppelklick auf das Logo oben links an der Karte. Die Karte verschwindet und nur das Logo bleibt."
L["Bring it back"] = "Zurückholen"
L["Double-click the logo again."] = "Noch ein Doppelklick auf das Logo."
L["Resize it"] = "Größe ändern"
L["Drag the map's bottom-right corner."] = "Zieh an der unteren rechten Ecke der Karte."
L["Any shape is on for this demo: drag the corner again to make the map wide or tall."] = "Beliebige Form ist für diese Demo an: Zieh erneut an der Ecke, um die Karte breit oder hoch zu machen."
L["Returning to original"] = "Zurück zum Original"
L["Size, shape and lock are in Options > Map window. Your own settings come back when the tutorial ends."] = "Größe, Form und Sperre stehen unter Optionen > Kartenfenster. Deine eigenen Einstellungen kehren zurück, wenn das Tutorial endet."
L["Back"] = "Zurück"
L["Sections"] = "Abschnitte"
L["Exit Tutorial"] = "Tutorial beenden"
L["Next"] = "Weiter"
L["Done!"] = "Geschafft!"
L["%s: step %d of %d"] = "%s: Schritt %d von %d"
L["Skip Step"] = "Schritt überspringen"
L["This step can't be done here right now. Skip it to go on."] = "Dieser Schritt geht hier gerade nicht. Überspring ihn, um weiterzumachen."
L["%s (done)"] = "%s (erledigt)"
L["The tutorial is already running."] = "Das Tutorial läuft bereits."
L["The tutorial can't start right now. Try again in a moment."] = "Das Tutorial kann gerade nicht starten. Versuch es gleich noch einmal."
L["The tutorial can't start in combat, in a dungeon, on a flight, while dead or while recording a walk. Try again after."] = "Das Tutorial kann nicht im Kampf, in einem Dungeon, auf einem Flug, tot oder beim Aufzeichnen eines Gangs starten. Versuch es danach noch einmal."
L["Tutorial started. Everything goes back to how you had it when it ends."] = "Tutorial gestartet. Am Ende wird alles wieder so, wie du es hattest."
L["That's the tour"] = "Das war die Tour"
L["Everything is back as you had it. Replay any part in Options > Help, or type /agps tutorial."] = "Alles ist wieder so, wie du es hattest. Spiel jeden Teil unter Optionen > Hilfe erneut ab oder gib /agps tutorial ein."
L["Tutorial closed: everything is back as you had it. Options > Help plays it again."] = "Tutorial geschlossen: alles ist wieder so, wie du es hattest. Optionen > Hilfe spielt es erneut ab."
L["Start Tutorial"] = "Tutorial starten"
L["Not Now"] = "Nicht jetzt"
L["Don't Ask Again"] = "Nicht mehr fragen"
L["Welcome to AzerothGPS"] = "Willkommen bei AzerothGPS"
L["What's new in %s"] = "Neu in %s"
L["Take a short tutorial? It shows the main features on your own map and puts everything back after. Options > Help plays it any time."] = "Ein kurzes Tutorial machen? Es zeigt die wichtigsten Funktionen auf deiner eigenen Karte und stellt danach alles wieder her. Optionen > Hilfe spielt es jederzeit ab."
L["Take a short tutorial of the new features? It uses your own map and puts everything back after. Options > Help plays it any time."] = "Ein kurzes Tutorial zu den neuen Funktionen machen? Es nutzt deine eigene Karte und stellt danach alles wieder her. Optionen > Hilfe spielt es jederzeit ab."
L["The tutorial was cut short, and everything is back as you had it. Carry on where you were?"] = "Das Tutorial wurde unterbrochen, und alles ist wieder so, wie du es hattest. Dort weitermachen, wo du warst?"
L["A short tour of the main features on your own map. Everything goes back to how you had it after."] = "Eine kurze Tour durch die wichtigsten Funktionen auf deiner eigenen Karte. Danach wird alles wieder so, wie du es hattest."
L["Play All"] = "Alle abspielen"
L["Play"] = "Abspielen"
L["Offer the tutorial after big updates"] = "Tutorial nach großen Updates anbieten"
L["Asks at login whether to take the tutorial when an update adds new sections to it."] = "Fragt beim Einloggen, ob du das Tutorial machen willst, wenn ein Update neue Abschnitte hinzufügt."
L["The tutorial isn't running."] = "Das Tutorial läuft nicht."
L["Tutorial sections: %s"] = "Tutorial-Abschnitte: %s"
L["/agps tutorial [section|exit]  (the tutorial, or one of its sections: Options > Help lists them)"] = "/agps tutorial [section|exit]  (das Tutorial oder einer seiner Abschnitte: Optionen > Hilfe listet sie auf)"
L["Example for the tutorial"] = "Beispiel für das Tutorial"
L["Check here to turn it on now."] = "Setze hier ein Häkchen, um sie jetzt einzuschalten."
L["Active!"] = "Aktiv!"
L["AzerothGPS can now replace your minimap!"] = "AzerothGPS kann jetzt deine Minikarte ersetzen!"
L["To save work, only the paths to the next stops are drawn (%d at a time). Every stop is still in the route: reach one for the next path to appear. Options > Performance to adjust this number."] = "Um Rechenarbeit zu sparen, werden nur die Wege zu den nächsten Stopps gezeichnet (%d auf einmal). Alle Stopps bleiben in der Route: Erreichst du einen, erscheint der nächste Weg. Die Anzahl stellst du unter Optionen > Leistung ein."
L["%s and %s"] = "%s und %s"
L["%s, and %s"] = "%s und %s"
L["Show the GPS map in the game's world map"] = "GPS-Karte in der Weltkarte des Spiels zeigen"
L["The GPS map shows in the game's own world map window (M) instead of a window of its own, with its route, buttons and map styles. The show/hide key, and the logo on the minimap square, open the world map."] = "Die GPS-Karte erscheint im Weltkartenfenster des Spiels (M) statt in einem eigenen Fenster, mit Route, Buttons und Kartenstilen. Die Anzeigen/Verbergen-Taste und das Logo am Minikartenquadrat öffnen die Weltkarte."
L["Left-click: the game's world map, with the GPS map in it."] = "Linksklick: die Weltkarte des Spiels, mit der GPS-Karte darin."
L["In the game's world map"] = "In der Weltkarte des Spiels"
L["The GPS map can also show in the game's world map (M) instead of its own window. Check here to use it after the tutorial, or later in Options > Map."] = "Die GPS-Karte kann auch in der Weltkarte des Spiels (M) statt in ihrem eigenen Fenster erscheinen. Setze hier ein Häkchen, um das nach dem Tutorial zu nutzen, oder später unter Optionen > Karte."
L["Drag to resize the world map"] = "Ziehen, um die Weltkarte zu vergrößern oder zu verkleinern"
L["Map icons"] = "Kartensymbole"
L["Apply (Reload UI)"] = "Anwenden (UI neu laden)"
L["Type /reload to apply it."] = "Gib /reload ein, um sie anzuwenden."
L["No settings found."] = "Keine Einstellungen gefunden."
L["Custom pins"] = "Eigene Pins"
L["Create a pin"] = "Einen Pin erstellen"
L["Hold Shift and click a spot on the map, then click Create Pin."] = "Halte Umschalt und klicke auf eine Stelle der Karte, dann auf Pin erstellen."
L["Name it"] = "Benenne ihn"
L["Type a name, pick an icon, then click Create Pin."] = "Gib einen Namen ein, wähle ein Symbol und klicke auf Pin erstellen."
L["Route to your pin"] = "Route zu deinem Pin"
L["Double-click your pin: it becomes a stop and the route goes to it."] = "Doppelklick auf deinen Pin: Er wird ein Halt, und die Route führt dorthin."
L["Find it in the search"] = "In der Suche finden"
L["Your pins are in Search Places too. Type its name in the search box: %s"] = "Deine Pins stehen auch in Orte suchen. Gib seinen Namen ins Suchfeld ein: %s"
L["Remove a pin"] = "Einen Pin entfernen"
L["Right-click a pin to remove it. The pin made in this tutorial is practice: it is removed when you move on."] = "Rechtsklick auf einen Pin entfernt ihn. Der Pin aus diesem Tutorial ist nur zum Üben: Er wird entfernt, wenn du weitergehst."
L["My pin"] = "Mein Pin"
