L["Quest Route: %s is in the route already."] = "Questroute: %s ist schon in der Route."
L["Quick Search: the Search Places button is turned off (Options > Quick buttons)."] = "Schnellsuche: Die Schaltfläche Orte suchen ist ausgeschaltet (Optionen > Schnellschaltflächen)."
